def transform(grid):
    n = len(grid)
    out = [[0] * (3 * n) for _ in range(3 * n)]
    for br in range(3):
        for bc in range(3):
            tile = [row[:] for row in grid]
            if br != 1:
                tile = tile[::-1]
            if bc != 1:
                tile = [row[::-1] for row in tile]
            for r in range(n):
                for c in range(n):
                    out[br * n + r][bc * n + c] = tile[r][c]
    return out

